insert into public.lessons_learned (id, tenant_id, project_id, title, description, challenges, recommendations, action_plan) values ('ll-wayuu-101', 'ten-wayuu', 'proj-wayuu-001', 'Estandarización de tarifas netas para el canal B2B', 'Durante la operación piloto de la Ruta Ancestral Jemeilli, se evidenció que las agencias mayoristas exigen tarifas netas fijas anualizadas con comisiones del 20% y seguros de accidentes.', 'Las asociaciones comunitarias cambiaban los costos de los almuerzos semanalmente según el precio de mercado, rompiendo reservas de agencias.', 'Establecer acuerdos de costos fijos estacionales por semestre con las asociaciones y contratar pólizas colectivas anuales.', '{"description":"Redactar acuerdo firmado de tarifas fijas para almuerzos con la cooperativa de Mayapo.","responsible":"Coordinador Territorial MEAL","deadline":"2026-07-15","status":"pending"}'::jsonb) on conflict (id) do nothing;
